{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Although system dynamics modeling has been utilized in various aspects of public health since the 1970s, past reviews in this field have noted a significant increase in their use since the early 2000s... The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied.",
      "reason": "The Introduction describes the current state of knowledge (growth of system dynamics in public health, calls for systems approaches in cancer control) and identifies the key uncertainty/gap: no prior study of its application to cancer prevention and control."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Standard bench and clinical research approaches alone are not well suited to account for this complexity... To overcome persistent barriers to providing high-quality, equitable care, approaches are needed to address this complexity and provide guidance for successful intervention.",
      "reason": "The Introduction explains the importance and need for the review by arguing that cancer's complexity requires systems approaches and that the specific application to cancer prevention and control has not been studied."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_3",
      "quote": "The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied.",
      "reason": "The manuscript states that no prior review of system dynamics modeling applied specifically to cancer prevention and control exists, so there is no similar systematic review to cite or update."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_3",
      "quote": "System dynamics is a multifaceted systems science approach for analyzing the complex interrelationships between variables in a system and the resulting nonlinear system behavior [16].",
      "reason": "This is a methods review of system dynamics modeling applications, not a review of intervention effects of a specific intervention, so describing a mechanism of action of an intervention does not apply."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_3",
      "quote": "Cancer is a complex, multilevel phenomenon [1-5] in which health outcomes depend on highly interrelated elements across stages of etiology, prevention, screening, diagnosis, treatment, survivorship, and end-of-life care [6, 7].",
      "reason": "The review is a methods review of system dynamics modeling studies rather than a review of a specific complex intervention, so a logic model of intervention components is not required."
    }
  ],
  "confidence": 88
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit statement of review objectives or questions is found in the retrieved evidence. The abstract only implies a gap ('the breadth, characteristics, and quality of these studies is not known') and the Introduction ends by noting 'The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied,' but neither states an explicit objective or research question, nor uses a question-formulation framework."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_2",
      "quote": "We searched PubMed, Scopus, APA PsycInfo, and eight peer-reviewed journals to identify cancer-related studies that used system dynamics modeling.",
      "reason": "This is a methods/characteristics review of system dynamics modeling studies, not a review of intervention effects, so planned PICO-style comparisons do not apply."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "Included articles: 1) were published in peer-reviewed journals; 2) were written in English; 3) used system dynamics modeling (i.e., causal-loop diagramming, stock-and-flow diagramming, or computational system dynamics modeling); 4) pertained to cancer prevention or control; and 4) were published within the last 10 years.",
      "reason": "Eligible study designs (system dynamics modeling types) and topic scope (cancer prevention or control) are specified, but settings, populations, and follow-up requirements are not described."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "1) were published in peer-reviewed journals; 2) were written in English; ... and 4) were published within the last 10 years.",
      "reason": "Report characteristics are specified: publication status (peer-reviewed), language (English), and dissemination year (last 10 years)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence distinguishes exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "most studies included a computational system dynamics simulation model (n = 21; 66%), while the remaining studies (n = 11; 34%) used only diagramming approaches (referred to as diagram-only studies in this review)",
      "reason": "Synthesis groups (simulation vs diagram-only; cancer control continuum focus areas) are described in Results, but the Methods do not explicitly specify groups for each synthesis or link them to review objective comparisons."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "This search period was selected to reflect recent developments and current applications of system dynamics modeling related to cancer.",
      "reason": "A rationale is provided for the 10-year restriction on publication date; additional rationales for excluding pathogenesis and non-cancer topics appear in the Limitations (text_20)."
    }
  ],
  "confidence": 85
}

